    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof saveReflection>>, TError,SaveReflectionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof saveReflection>>, TError,SaveReflectionMutationVariables, TContext> => {

const mutationKey = getSaveReflectionMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof saveReflection>>, SaveReflectionMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  saveReflection(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SaveReflectionMutationResult = NonNullable<Awaited<ReturnType<typeof saveReflection>>>
    export type SaveReflectionMutationBody = BodyType<ReflectionInput>
    export type SaveReflectionMutationError = ErrorType<ErrorResponseResponse>
    export type SaveReflectionMutationVariables = {id: string;data: BodyType<ReflectionInput>}

    /**
 * @summary Save a reflection
 */
export const useSaveReflection = <TError = ErrorType<ErrorResponseResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof saveReflection>>, TError,SaveReflectionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof saveReflection>>,
        TError,
        SaveReflectionMutationVariables,
        TContext
      > => {
      return useMutation(getSaveReflectionMutationOptions(options));
    }

export const getAnalyzeEventUrl = (id: string,) => {




  return `/api/events/${id}/analyze`
}

/**
 * AI output is advisory only and is not persisted as an event decision.
 * @summary Generate AI candidates for explicit user review and saving
 */
export const analyzeEvent = async (id: string,
    analysisInput: AnalysisInput, options?: Parameters<typeof customFetch>[1]): Promise<AnalysisResult> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<AnalysisResult>(getAnalyzeEventUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(analysisInput)
  }
);}





