export const getListPredictionsUrl = () => {




  return `/api/predictions`
}

/**
 * @summary List events that have predictions
 */
export const listPredictions = async ( options?: Parameters<typeof customFetch>[1]): Promise<Event[]> => {

  return customFetch<Event[]>(getListPredictionsUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListPredictionsQueryKey = () => {
    return [
    `/api/predictions`
    ] as const;
    }


export const getListPredictionsQueryOptions = <TData = Awaited<ReturnType<typeof listPredictions>>, TError = ErrorType<ErrorResponseResponse>>( options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listPredictions>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListPredictionsQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listPredictions>>> = ({ signal }) => listPredictions({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listPredictions>>, TError, TData> & { queryKey: QueryKey }
}

export type ListPredictionsQueryResult = NonNullable<Awaited<ReturnType<typeof listPredictions>>>
export type ListPredictionsQueryError = ErrorType<ErrorResponseResponse>


/**
 * @summary List events that have predictions
 */

export function useListPredictions<TData = Awaited<ReturnType<typeof listPredictions>>, TError = ErrorType<ErrorResponseResponse>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listPredictions>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getListPredictionsQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







